//! 🧪️ A moved static child owns the same original source through callback and paid parent return.
use super::*;
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn now()->Option<u64>{Some(1000)}
fn static_source<T:Send+'static>(_:&T){}
#[test]
fn original_owned_caller_source_loan_preserves_static_roots_actual_turn_and_paid_parent_return(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let grant:RetainedCloneGrant=serde_json::from_value(policy["grant"].clone()).unwrap();let operation=OperationId(policy["operation"].as_u64().unwrap());let generation=Generation(policy["generation"].as_u64().unwrap());let budget=||StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadline"].as_u64().unwrap(),grant);
 for cut in policy["cuts"].as_array().unwrap(){let cut=cut.as_u64().unwrap();let((cancel,root_birth),heap)=observe(||CancelToken::admit_root(grant).unwrap().unwrap());assert_eq!(heap,(root_birth.retained_capacity_bytes,0));let mut born=heap.0;let((authority,ledger_birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!(heap,(ledger_birth.retained_capacity_bytes,0));born+=heap.0;let ledger=Arc::as_ptr(authority.original().unwrap());let((mut parent,source_birth),heap)=observe(||OriginalCallerSourceParent::admit(authority,cancel,grant).ok().unwrap());assert_eq!(heap,(source_birth.retained_capacity_bytes,0));born+=heap.0;static_source(&parent);let source=parent.original.as_ref().unwrap().identity();let mut sequence=0;
  if cut>0{for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut recipient=Default::default();let mut cx=parent.borrow_context(StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadline"].as_u64().unwrap(),denied),now,&mut sequence,&mut recipient).unwrap();let(result,heap)=observe(||parent.admit_loan(&mut cx).unwrap());assert!(result.is_none());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),Default::default())}
   let mut recipient=Default::default();let mut cx=parent.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(mut loan,heap)=observe(||parent.admit_loan(&mut cx).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),metadata());static_source(&loan);drop(cx);let(refused,heap)=observe(||parent.close_step(grant));assert!(refused.is_err());assert_eq!(heap,(0,0));assert_eq!(parent.original.as_ref().unwrap().identity(),source);
   if cut==2{let mut recipient=Default::default();let mut cx=parent.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let recipient_identity=cx.original_recipient_identity();let(returned,heap)=observe(||loan.run_close(&mut cx,grant,|actual|{assert_eq!(actual.operation(),operation);assert_eq!(actual.generation(),generation);assert_eq!(actual.deadline_us(),policy["deadline"].as_u64().unwrap());assert_eq!(actual.fuel_remaining(),policy["fuel"].as_u64().unwrap());assert!(std::ptr::fn_addr_eq(actual.clock_source(),now as fn()->Option<u64>));assert_eq!(actual.original_recipient_identity(),recipient_identity);assert_eq!(Arc::as_ptr(&actual.payload_ledger),ledger);let mut target=[0;7];target.copy_from_slice(b"source!");assert_eq!(&target,b"source!");let progress=RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()};actual.consume_retained(progress)?;Ok(InteractiveJobCloseStep::Pending{progress})}).unwrap());assert_eq!(heap,(0,0));assert!(returned.receipt_refusal().is_none());assert_eq!(cx.retained_progress(),serde_json::from_value(policy["callbackReceipt"].clone()).unwrap());assert_eq!(returned.into_original().unwrap().unwrap().progress(),cx.retained_progress());drop(cx);
    let mut recipient=Default::default();let mut cx=parent.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(returned,heap)=observe(||loan.run_close(&mut cx,grant,|actual|{actual.consume_retained(metadata())?;let mut failure=OriginalTurnFailure::from(ValueError::literal(ValueRefusalKind::InvalidValue,"original static child failed").with_retained_progress(metadata()));failure.receipt_refusal=Some(ValueError::literal(ValueRefusalKind::DepthLimit,"original static child receipt refused"));Err(failure)}).unwrap());assert_eq!(heap,(0,0));let failure=returned.into_original().unwrap().unwrap_err();assert!(matches!(failure.primary,OriginalTurnPrimary::Value(ref value)if value.message()=="original static child failed"));assert_eq!(failure.receipt_refusal.as_ref().unwrap().kind,ValueRefusalKind::DepthLimit);assert_eq!(cx.retained_progress(),metadata());assert_eq!(observe(||drop(failure)).1,(0,0));drop(cx);
   }
   parent.original.as_ref().unwrap().get().cancel.cancel_now();for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let mut recipient=Default::default();let mut cx=parent.borrow_context(StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadline"].as_u64().unwrap(),denied),now,&mut sequence,&mut recipient).unwrap();let(step,heap)=observe(||loan.close_step(&parent,&mut cx).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default());assert!(!loan.terminal_is_empty())}let mut recipient=Default::default();let mut cx=parent.borrow_context(budget(),now,&mut sequence,&mut recipient).unwrap();let(step,heap)=observe(||loan.close_step(&parent,&mut cx).unwrap());assert_eq!(heap,(0,0));assert_eq!(cx.retained_progress(),metadata());assert_eq!(step.progress(),metadata());assert!(loan.terminal_is_empty());assert_eq!(parent.original.as_ref().unwrap().identity(),source);assert_eq!(observe(||drop(loan)).1,(0,0));drop(cx);
  }
  let mut released=0;for _ in 0..16{if parent.terminal_is_empty(){break}let demand=parent.retirement_demands().unwrap();for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant},RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}]{if denied.maximum_release_bytes==0&&demand.release_bytes==0{continue}let(step,heap)=observe(||parent.close_step(denied).unwrap());assert_eq!(heap,(0,0));assert_eq!(step.progress(),Default::default())}let(step,heap)=observe(||parent.close_step(grant).unwrap());assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));born+=heap.0;released+=heap.1;assert!(step.progress().fits(grant))}assert!(parent.terminal_is_empty());assert_eq!(observe(||drop(parent)).1,(0,0));assert_eq!(born,released);eprintln!("[DEBUG] originalOwnedSource cut={cut} staticLoan=true sameLedger=true sameSource=true actualIncomingClockFuelDeadlineRecipient=true wholeFailure=true directPaidAliasReturn=true birthRelease={born} terminalDrop0=true");
 }
}
